// Kleene 3-valued helpers (T>U>F)
const ord = { 'F':0, 'U':1, 'T':2 };
function min3(a,b){ return ord[a] < ord[b] ? a : b; }
function max3(a,b){ return ord[a] > ord[b] ? a : b; }
function not(a){ return a==='T'?'F': a==='F'?'T':'U'; }
function imp(a,b){ // a→b = (¬a) ∨ b
  return max3(not(a), b);
}
